  throw new Error(
    `expiresIn=${expiresIn} is outside the presigned URL lifetime range: expected an integer ` +
      `between 1 and ${PRESIGNED_URL_MAX_EXPIRES_SECONDS} seconds (seven days). Pass a shorter expiry to getUrl().`,
  );
